function.arguments:
{
  "database": "video_game_store",
  "collection": "Customers",
  "pipeline": [
    {
      "$match": {
        "Purchase Date": {
          "$gte": { "$date": "2023-01-01T00:00:00Z" },
          "$lt":  { "$date": "2024-01-01T00:00:00Z" }
        }
      }
    },
    {
      "$addFields": {
        "genre_norm":   { "$toLower": "$Game Genre" },
        "age_group_norm": { "$ifNull": ["$Age Group", "Unknown"] },
        "member_norm":  { "$trim": { "input": { "$toLower": "$Membership Status" } } }
      }
    },
    { "$match": { "genre_norm": "action" } },
    {
      "$group": {
        "_id": { "age_group": "$age_group_norm", "membership": "$member_norm" },
        "purchase_count": { "$sum": 1 },
        "total_amount":   { "$sum": "$Purchase Amount" }
      }
    },
    {
      "$project": {
        "_id": 0,
        "Age Group": "$_id.age_group",
        "Membership Status": "$_id.membership",
        "purchase_count": 1,
        "total_amount": 1
      }
    },
    { "$sort": { "Age Group": 1, "Membership Status": 1 } }
  ]
}

